import * as T from './vendor/three.module.js';
import {rockPassage,currentZone,canUseAbility,claimAbilityTreasure} from './abilities.js';
export function createAbilityWorld({scene,state,ground,blocked,inv,save,message,sound}){
 const solids=[],decor=new T.Group();scene.add(decor);const x=rockPassage.x,z=rockPassage.z,y=ground(x,z,true);
 function block(px,py,pz,w,h,d,color,solid=false){const m=new T.Mesh(new T.BoxGeometry(w,h,d),new T.MeshLambertMaterial({color}));m.position.set(px,py,pz);decor.add(m);if(solid)solids.push({m,x:px,z:pz,y:py,h,w,d});return m;}
 const boulder=block(x,y+1.6,z,5,3.2,1.8,0x8d947e,true);boulder.visible=!state.opened;
 // Golden seams distinguish ability rocks from ordinary mineable stone.
 const seams=new T.Group();decor.add(seams);for(let i=-1;i<=1;i++){const m=new T.Mesh(new T.BoxGeometry(.13,2,.05),new T.MeshBasicMaterial({color:0xffd56b}));m.position.set(x+i*1.25,y+1.6,z+.93);m.rotation.z=i*.22;seams.add(m);}seams.visible=!state.opened;
 block(x-3.2,y+2,z-2,1.4,4,8,0x707f79,true);block(x+3.2,y+2,z-2,1.4,4,8,0x707f79,true);block(x,y+2,z-6,7.8,4,1,0x707f79,true);
 function chest(px,py,pz){const g=new T.Group(),base=new T.Mesh(new T.BoxGeometry(.95,.6,.65),new T.MeshLambertMaterial({color:0xa37343}));base.position.y=.3;g.add(base);for(const a of [-.32,.32]){const band=new T.Mesh(new T.BoxGeometry(.09,.68,.7),new T.MeshLambertMaterial({color:0xffd46a}));band.position.set(a,.34,0);g.add(band);}g.position.set(px,py,pz);scene.add(g);return g;}
 const chests=[{id:'horns',g:chest(x,ground(x,z-4,true),z-4)},{id:'current',g:chest(currentZone.x,ground(currentZone.x,currentZone.z,true),currentZone.z)}];
 const bubbles=new T.Group();scene.add(bubbles);for(let i=0;i<18;i++){const m=new T.Mesh(new T.SphereGeometry(.12,5,4),new T.MeshBasicMaterial({color:0x9df2e8,transparent:true,opacity:.6}));m.userData.phase=i;m.position.set(currentZone.x+Math.sin(i*2.4)*3,-3,currentZone.z+Math.cos(i*2.4)*3);bubbles.add(m);}
 function blocksMove(px,py,pz){return solids.some(s=>s.m.visible&&Math.abs(px-s.x)<s.w/2+.3&&Math.abs(pz-s.z)<s.d/2+.3&&py>s.y-s.h/2-.2&&py<s.y+s.h/2+1.4);}
 function crush(d,pos,yaw){if(!canUseAbility(d,0))return false;if(state.opened){message('Ce passage est déjà ouvert ! Cherche le coffre derrière.');return false;}const dx=x-pos.x,dz=z-pos.z;if(Math.hypot(dx,dz)>5||Math.abs(pos.y-y-1.65)>2.5||(-Math.sin(yaw)*dx-Math.cos(yaw)*dz)<.3){message('🪨 Approche des rochers dorés et regarde-les. Le carnet indique le passage.');return false;}if(blocked(pos,new T.Vector3(x,y+1.5,z))){message('Un bloc gêne ton tricératops. Approche par l’entrée.');return false;}state.opened=true;boulder.visible=false;seams.visible=false;inv.stone+=6;sound('break');message('🦕 Bravo ! Passage ouvert · +6 pierres. Un coffre t’attend !');save();return true;}
 function update(time,pos,d){for(const b of bubbles.children)b.position.y=-7+((time*.8+b.userData.phase*.43)%6);for(const c of chests){c.g.visible=!state.treasures.includes(c.id);if(!c.g.visible)continue;const p=c.g.position.clone().add(new T.Vector3(0,c.id==='current'?2.3:.7,0));if(pos.distanceTo(p)>3||blocked(pos,p))continue;if(c.id==='current'&&pos.y>=-2)continue;const n=claimAbilityTreasure(state,inv,c.id,d);if(n){c.g.visible=false;sound('treasure');message('🎁 Passage exploré ! +'+n+' diamants');save();}}}
 const ray=new T.Raycaster();function blocksRay(a,b,ignoreBoulder=false){const delta=b.clone().sub(a),distance=delta.length();if(distance<.01)return false;ray.set(a,delta.normalize());ray.far=distance;const meshes=solids.filter(s=>s.m.visible&&(!ignoreBoulder||s.m!==boulder)).map(s=>s.m);for(const m of meshes)m.updateMatrixWorld(true);return ray.intersectObjects(meshes,false).length>0;}return {blocksMove,blocksRay,crush,update};
}
